{
  "title": "이동·화물·지도·관측 작동 계약",
  "authority": {
    "sealedRowsApplied": [
      {
        "row": "D02",
        "decisionId": "GP-02",
        "chosenOption": "A",
        "scope": "구간별 관측 시점, 사건 기반 정보 신선도, 차단 구간 재계획의 방향"
      },
      {
        "row": "D28",
        "decisionId": "GP-02",
        "chosenOption": "A",
        "scope": "개인 이동은 Lite Move/짐 구조를 참고하고 야외·터널 보정은 서울 별도표로 분리"
      }
    ],
    "rowIdsAreNotDomainIds": true,
    "priorApprovedRules": [
      "actual movement; no strategic teleport",
      "stable identity and explicit version conflicts",
      "cargo material conservation and provenance-linked split",
      "verified arrival at or before cutoff is temporally eligible",
      "same-time arrival verification precedes reservation, production and consumption",
      "receiver countersign is required by the selected cargo policy",
      "any unit actually arriving while battle is ongoing may reinforce",
      "map marks and reports do not become current world fact",
      "movement/encounter/observation RNG is separated from other purposes"
    ],
    "gurpsLikeBasis": {
      "classification": "public-Lite-derived-structure-plus-Seoul-owned-values",
      "anchors": [
        "L-lift",
        "L-secondary",
        "L-encumbrance"
      ],
      "adoptionBoundary": "Lite supplies personal Basic Lift, Basic Move and encumbrance row structure only. It does not supply Seoul route distance, strategic time, fatigue, tunnel modifiers, cargo receipt law or information freshness duration.",
      "noGurps2004Claim": true
    },
    "noNewOwnerDecisions": true
  },
  "workedExamples": [
    {
      "id": "personal-load-boundary",
      "kind": "normal-boundary",
      "input": {
        "ST": 10,
        "DX": 12,
        "HT": 12,
        "loadLb": 40
      },
      "work": "BL=10^2/5=20 lb; BasicSpeed=(12+12)/4=6; BasicMove=6; load=2*BL selects level1; floor(6*0.8)=4.",
      "expected": {
        "BLraw": 20,
        "BLrounded": 20,
        "basicSpeed": 6,
        "basicMove": 6,
        "encumbranceLevel": 1,
        "personalMove": 4
      },
      "authority": [
        "L-lift",
        "L-secondary",
        "L-encumbrance"
      ],
      "valueStatus": "illustrative Seoul-owned inputs; coefficients are public Lite reference structure"
    },
    {
      "id": "exact-cutoff-delivery",
      "kind": "boundary",
      "input": {
        "arrivalAt": 600,
        "cutoffAt": 600,
        "verifiedArrival": true,
        "receiverCountersigned": true,
        "otherApplicableGuards": true
      },
      "work": "600 <= 600, so temporal eligibility is true. Receiver countersign and supplied other guards make this fixture available; cutoff alone would not.",
      "expected": {
        "temporalEligibility": true,
        "finalAvailable": true
      },
      "authority": [
        "T68-CARGO-INCLUSIVE-CUTOFF",
        "selected receiver-countersign policy"
      ],
      "valueStatus": "illustrative clock coordinates, not an approved day length"
    },
    {
      "id": "split-cargo",
      "kind": "normal",
      "input": {
        "parent": [
          "a",
          "b",
          "c",
          "d",
          "e"
        ],
        "children": [
          [
            "a",
            "b"
          ],
          [
            "c",
            "d",
            "e"
          ]
        ]
      },
      "work": "Child sets are disjoint and union to the parent; 2+3=5, then parent retires.",
      "expected": {
        "childQuantities": [
          2,
          3
        ],
        "activeQuantity": 5,
        "parentStatus": "retired"
      },
      "authority": [
        "selected split-provenance policy",
        "material conservation"
      ],
      "valueStatus": "illustrative atom identities"
    },
    {
      "id": "stale-control-report",
      "kind": "adversarial",
      "input": {
        "worldControl": "blocked",
        "reportControl": "open",
        "observedAt": 700,
        "sourceAsOf": 650
      },
      "work": "The report updates observer knowledge as-of 650 at receipt 700; it does not overwrite current blocked world state.",
      "expected": {
        "worldControl": "blocked",
        "knowledge": {
          "status": "open",
          "observedAt": 700,
          "asOf": 650
        }
      },
      "authority": [
        "sealed GP-02-A",
        "report is not world fact"
      ],
      "valueStatus": "illustrative clock coordinates"
    },
    {
      "id": "legal-layer-connection",
      "kind": "failure-adversarial",
      "input": {
        "mapMark": true,
        "routeConnected": true,
        "passageAuthorized": false,
        "segmentPassable": true
      },
      "work": "A visible map mark and physical connection do not replace passage authority; conjunction is false.",
      "expected": {
        "legal": false,
        "error": "E_ROUTE_AUTHORITY"
      },
      "authority": [
        "GP-02-A direction",
        "no invented movement edges"
      ],
      "valueStatus": "predicate fixture"
    },
    {
      "id": "ongoing-versus-ended-reinforcement",
      "kind": "boundary",
      "input": {
        "arrivalVerified": true,
        "ongoing": "ongoing",
        "ended": "ended"
      },
      "work": "Verified arrival joins an ongoing battle and cannot join an ended battle.",
      "expected": {
        "ongoingMayJoin": true,
        "endedMayJoin": false
      },
      "authority": [
        "OWNER-REINFORCEMENT-20261004"
      ],
      "valueStatus": "symbolic battle states"
    }
  ],
  "sourceComparisons": {
    "ck3": "Documentary parameters and fragments remain comparison evidence. Exact coordinate units, general native distance/speed/load/fatigue/residual/freshness algorithms and same-tick cutoff ordering are not verified or adopted.",
    "norland": "Road and status modifiers are mixed historical revisions. Distance, load and residual segment algorithms remain unresolved; no historical value becomes a Seoul coefficient."
  }
}
